export const ONELINER_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/oneliner-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getOneLinerStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(ONELINER_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
